def pp(a,k,n):
    res=[]
    for i in range(a,n+1):
        if i%k==0:
            res.append(i-a)
    return res
L=list(map(int,input().split()))
a=L[0]
k=L[1]
n=L[2]
result=pp(a,k,n)
if len(result)==0:
    print(-1)
else:
    print(*result)

